prefs_parsed = [(line.split('|')[1].split('=')[1], float(line.split('|')[2].split('=')[1])) for line in preference_lines]

# Aggregate scores for each action by max score seen
action_best_score = {}
for action, score in prefs_parsed:
    if action not in action_best_score or score > action_best_score[action]:
        action_best_score[action] = score

# Sort actions by their best score descending
sorted_actions = sorted(action_best_score.items(), key=lambda x: x[1], reverse=True)

print("Candidate actions from context: ", candidate_lines[0].strip())
print("Actions and their highest scores seen in context:")
for action, score in sorted_actions:
    print(f"  - {action}: {score}")

